mapper.delete:
DELETE FROM category_age_tier_baseline
WHERE baseline_month = #{baselineMonth}

    AND marketplace = #{marketplace}

mapper.insert:
INSERT INTO category_age_tier_baseline ( marketplace, bsr_id, age_bucket, baseline_month, sample_size, units_p25, units_p50, units_p75, units_p90, bsr_p10, bsr_p25, bsr_p50, bsr_p75, price_p50, confidence, computed_at ) WITH filtered AS ( SELECT cp.marketplace, cp.bsr_id, cp.units, cp.bsr, cp.price, CASE WHEN cp.listing_days < 30 THEN '0_30' WHEN cp.listing_days < 60 THEN '30_60' ELSE '60_90' END AS age_bucket FROM competitor_products_clean cp WHERE cp.month = #{baselineMonth} AND cp.listing_days IS NOT NULL AND cp.listing_days < 90 AND cp.weight_g IS NOT NULL AND cp.weight_g < 300 AND cp.bsr_id IS NOT NULL AND cp.bsr_id != '' AND LOWER(cp.bsr_id) != 'null' AND cp.bsr IS NOT NULL AND cp.bsr > 0 AND cp.units IS NOT NULL
AND cp.marketplace = #{marketplace}
), ranked AS ( SELECT marketplace, bsr_id, age_bucket, units, bsr, price, PERCENT_RANK() OVER ( PARTITION BY marketplace, bsr_id, age_bucket ORDER BY units ASC ) AS units_pr, PERCENT_RANK() OVER ( PARTITION BY marketplace, bsr_id, age_bucket ORDER BY bsr ASC ) AS bsr_pr FROM filtered ), agg AS ( SELECT marketplace, bsr_id, age_bucket, COUNT(*) AS sample_size, MAX(CASE WHEN units_pr <= 0.25 THEN units END) AS units_p25, MAX(CASE WHEN units_pr <= 0.50 THEN units END) AS units_p50, MAX(CASE WHEN units_pr <= 0.75 THEN units END) AS units_p75, MAX(CASE WHEN units_pr <= 0.90 THEN units END) AS units_p90, MAX(CASE WHEN bsr_pr <= 0.10 THEN bsr END) AS bsr_p10, MAX(CASE WHEN bsr_pr <= 0.25 THEN bsr END) AS bsr_p25, MAX(CASE WHEN bsr_pr <= 0.50 THEN bsr END) AS bsr_p50, MAX(CASE WHEN bsr_pr <= 0.75 THEN bsr END) AS bsr_p75, ROUND(AVG(price), 2) AS price_p50 FROM ranked GROUP BY marketplace, bsr_id, age_bucket HAVING COUNT(*) >= 30 ) SELECT marketplace, bsr_id, age_bucket, #{baselineMonth} AS baseline_month, sample_size, units_p25, units_p50, units_p75, units_p90, bsr_p10, bsr_p25, bsr_p50, bsr_p75, price_p50, -- confidence: high (≥100 且分位不塌缩), mid (≥50), low (其他/塌缩) CASE WHEN sample_size >= 100 AND units_p50 != units_p75 AND units_p75 != units_p90 THEN 'high' WHEN sample_size >= 50 AND units_p50 != units_p75 AND units_p75 != units_p90 THEN 'mid' ELSE 'low' END AS confidence, NOW() AS computed_at FROM agg
